\title{\bfseries Parity-Corrected Asymptotics for the\\ Information-Free Village Game}
\author{Aristotle}
\date{23 August 2026}

\begin{document}
\maketitle

\begin{abstract}
We analyse the \emph{information-free} version of the classical village-versus-wolves
elimination game, in which the daily vote is a uniform draw over the surviving population
and the wolves eliminate one villager each night. The structural observation driving the
analysis is that the total population decreases by exactly two per round regardless of the
outcome of the vote, so that the parity of the initial population $n$ is a conserved
quantity of the dynamics, propagated unchanged until absorption.

We prove that this conserved parity is not washed out in the large-population limit.
Writing $p_k(n)$ for the probability that the wolves win a game with initial population
$n$ containing $k$ wolves, we show that for every fixed $k \ge 1$ the rescaled sequence
$\sqrt{n}\,p_k(n)$ \emph{does not converge}; instead it has two distinct subsequential
limits,
\[
  \sqrt{n}\,p_k(n) \longrightarrow k\sqrt{2/\pi} \quad (n \text{ even}),
  \qquad
  \sqrt{n}\,p_k(n) \longrightarrow k\sqrt{\pi/2} \quad (n \text{ odd}),
\]
whose ratio is exactly $\pi/2$, independently of $k$. Equivalently, the village win
probability admits two asymptotic expansions with a common leading term $1$ and different
first-order coefficients. The mechanism is an exact pair of identities relating the two
parity subsequences of a single survival product $s(n)$: their pointwise product is
$1/(n+1)$ and their pointwise ratio is a Wallis partial product. We also give a
non-asymptotic form of the dichotomy valid at \emph{every} population --- the quantity
$n\,s(n)^2$ lies strictly below $1$ for even $n$ and at or above $1$ for odd $n$, the
separator $1$ being exactly the geometric mean of the two limiting constants --- and a
sharp quantitative control of the union bound,
$0 \le k\,s(n) - p_k(n) \le \binom{k}{2}/n$, with the constant attained. Finally we solve
the two-wolf game in closed form and compute the exact $1/n$ coefficient of the
union-bound defect for two, three and four wolves, exhibiting a second-order parity split
that is \emph{rational} on the odd fibre and \emph{Wallis-valued} on the even fibre.
\end{abstract}

\noindent\textbf{Keywords.} conserved parity; Wallis product; elimination games; union
bound; absorbing Markov chain; subsequential limits; second-order asymptotics.

\section{Introduction}

\subsection{The model}

Fix two non-negative integers $v$ and $k$: the number of villagers and the number of
wolves. The total population is $n = v+k$. Play proceeds in rounds, each consisting of a
day followed by a night.

\begin{itemize}
  \item \textbf{Day.} One living player, drawn uniformly at random from all $n$ living
  players, is eliminated. The uniformity is the \emph{information-free} assumption: no
  player possesses any information distinguishing wolves from villagers, so the vote is a
  pure random draw.
  \item \textbf{Night.} If at least one wolf survives the day, the wolves eliminate one
  villager.
\end{itemize}

The \emph{village wins} as soon as every wolf has been eliminated; the \emph{wolves win}
as soon as every villager has been eliminated. Both absorbing events are reached in
finitely many rounds, so the game terminates almost surely.

\begin{definition}[wolf-win probability]\label{def:F}
Let $F(v,k)$ denote the probability that the wolves win, starting from $v$ villagers and
$k$ wolves at the beginning of a day. Then $F(0,0)=0$, $F(0,k)=1$ for $k \ge 1$,
$F(v,0)=0$ for all $v$, and for $v,k \ge 1$
\[
  F(v,k) \;=\; \frac{k}{v+k}\,F(v-1,k-1) \;+\; \frac{v}{v+k}\,F(v-2,k),
\]
with $F(-1,k)$ read as $F(0,k)$. The \emph{village win probability} is
$V(v,k) = 1 - F(v,k)$.
\end{definition}

The two branches encode the two possible outcomes of the day. With probability $k/(v+k)$
the vote \emph{hits} a wolf; that wolf dies by day and one villager is eaten at night, so
the state becomes $(v-1,k-1)$. With probability $v/(v+k)$ the vote \emph{misses}; a
villager dies by day and another is eaten by night, so the state becomes $(v-2,k)$. It is
immediate by induction that $0 \le F(v,k) \le 1$.

When indexing by population rather than by villager count we write
$p_k(n) = F(n-k,k)$ for $n \ge k$.

\subsection{The conserved parity}

\begin{observation}\label{obs:parity}
In every round, hit or miss, the total population decreases by exactly two.
\end{observation}

Indeed, on a hit the state goes from $(v,k)$ to $(v-1,k-1)$, and on a miss from $(v,k)$ to
$(v-2,k)$; in both cases $v+k$ drops by $2$. Consequently the game visits only the
populations $n, n-2, n-4, \dots$, and \textbf{the parity of $n$ is a conserved quantity of
the dynamics}, preserved until absorption. The two parity classes are dynamically
disjoint: no trajectory ever crosses between them. The content of this paper is that this
microscopic conservation law survives the limit $n \to \infty$.

\subsection{Summary of results}

Throughout, $s(n)$ denotes the single-wolf survival product of
Definition~\ref{def:surv}.

\begin{enumerate}
  \item $p_1(n) = s(n)$ exactly, for every $n \ge 1$ (Theorem~\ref{thm:onewolf}).
  \item $s(n)s(n+1) = 1/(n+1)$ and $s(2m+1) = W_m\,s(2m)$, where $W_m$ is the $m$-th
  Wallis partial product (Theorems~\ref{thm:coupling}, \ref{thm:wallisratio}).
  \item $(2m+1)s(2m+1)^2 = W_m$ and $(2m+1)s(2m)^2W_m = 1$ (Theorem~\ref{thm:sq}).
  \item $\sqrt{n}\,s(n) \to \sqrt{2/\pi}$ along even $n$ and $\to \sqrt{\pi/2}$ along odd
  $n$ (Theorems~\ref{thm:oddlim}, \ref{thm:evenlim}).
  \item $p_k(n) \le k\,s(n)$ for all $n,k$ (Theorem~\ref{thm:union}).
  \item $0 \le n\bigl(k\,s(n) - p_k(n)\bigr) \le \binom{k}{2}$, and the constant is
  attained for $k=2,3$ at every odd population
  (Theorems~\ref{thm:sharp}, \ref{thm:optimal}).
  \item Two asymptotic expansions with ratio $\pi/2$, and no parity-blind limit
  (Theorem~\ref{thm:main}, Corollary~\ref{cor:expansions}).
  \item $n\,s(n)^2 < 1$ for even $n$ and $\ge 1$ for odd $n$
  (Theorem~\ref{thm:separator}).
  \item Exact closed forms for $k \le 4$ and the second-order parity split
  (Theorems~\ref{thm:twowolves}, \ref{thm:secondorder}).
\end{enumerate}

\section{The survival product and the one-wolf game}

\begin{definition}[survival product]\label{def:surv}
Define $s : \NN \to \QQ$ by
\[
  s(0) = s(1) = 1, \qquad s(n) = s(n-2)\cdot\frac{n-1}{n} \quad (n \ge 2).
\]
\end{definition}

Unfolding the recursion,
\[
  s(2m) = \prod_{j=1}^{m}\frac{2j-1}{2j} = \frac{1}{4^m}\binom{2m}{m},
  \qquad
  s(2m+1) = \prod_{j=1}^{m}\frac{2j}{2j+1} = \frac{4^m}{(2m+1)\binom{2m}{m}}.
\]
Probabilistically, $s(n)$ is the probability that a designated player survives every day
vote in a game whose population follows the deterministic ladder $n, n-2, n-4, \dots$,
since the survival probability on the round starting at population $j$ is $1-1/j$.

\begin{lemma}\label{lem:survbasic}
$0 < s(n) \le 1$ for all $n$, and $s(n+2) \le s(n)$.
\end{lemma}

\begin{proof}
Both statements follow by two-step induction from $s(n+2) = s(n)\frac{n+1}{n+2}$ and
$0 < \frac{n+1}{n+2} < 1$.
\end{proof}

\begin{theorem}[exact one-wolf formula]\label{thm:onewolf}
For every $v \ge 0$, $F(v,1) = s(v+1)$; equivalently $p_1(n) = s(n)$.
\end{theorem}

\begin{proof}
With a single wolf the wolves win if and only if that wolf is never selected by a day
vote, and the population ladder is deterministic, so the answer is the product
$\prod (1-1/n_i) = s(n)$. Formally: for $v=0$ both sides are $1$; for $v=1$ both sides are
$1/2$; and for $v \ge 2$ the recursion together with $F(\cdot,0)=0$ gives
\[
  F(v,1) = \frac{1}{v+1}\cdot 0 + \frac{v}{v+1}F(v-2,1)
         = \frac{v}{v+1}\,s(v-1) = s(v+1). \qedhere
\]
\end{proof}

\begin{theorem}[parity coupling]\label{thm:coupling}
For every $n \ge 0$, $\; s(n)\,s(n+1) = \dfrac{1}{n+1}$.
\end{theorem}

\begin{proof}
Induction on $n$. For $n=0$ both sides equal $1$. Assuming the identity at $n$,
\[
  s(n+1)s(n+2) = s(n+1)\,s(n)\,\frac{n+1}{n+2}
  = \frac{1}{n+1}\cdot\frac{n+1}{n+2} = \frac{1}{n+2}. \qedhere
\]
\end{proof}

This identity pins the product of the two parity subsequences exactly, and supplies one of
the two equations that will determine both parity constants.

\section{Wallis identities and the two square-root limits}

\begin{definition}[Wallis partial product]\label{def:wallis}
$\displaystyle W_m = \prod_{j=1}^{m}\frac{(2j)^2}{(2j-1)(2j+1)}$, with $W_0 = 1$.
\end{definition}

Wallis's classical result of 1656 is that $W_m \uparrow \pi/2$. This is the only fact
about $\pi$ that we use.

\begin{theorem}[Wallis ratio]\label{thm:wallisratio}
For every $m \ge 0$, $\; s(2m+1) = W_m\,s(2m)$.
\end{theorem}

\begin{proof}
Induction on $m$; at $m=0$ both sides equal $1$. For the step use
$s(2m+3) = s(2m+1)\frac{2m+2}{2m+3}$, $s(2m+2) = s(2m)\frac{2m+1}{2m+2}$ and
$W_{m+1} = W_m\frac{(2m+2)^2}{(2m+1)(2m+3)}$; substituting the inductive hypothesis and
clearing denominators yields a polynomial identity.
\end{proof}

\begin{theorem}[exact squared identities]\label{thm:sq}
For every $m \ge 0$,
\[
  (2m+1)\,s(2m+1)^2 = W_m,
  \qquad
  (2m+1)\,s(2m)^2\,W_m = 1.
\]
\end{theorem}

\begin{proof}
Theorem~\ref{thm:coupling} at $n=2m$ reads $(2m+1)s(2m)s(2m+1) = 1$. Substituting
$s(2m+1) = W_m s(2m)$ from Theorem~\ref{thm:wallisratio} gives the second identity;
substituting instead $s(2m) = s(2m+1)/W_m$ gives the first.
\end{proof}

These identities hold exactly for every $m$: no error terms. They are the arithmetic heart
of the paper.

\begin{theorem}[odd-population limit]\label{thm:oddlim}
$\displaystyle \lim_{m\to\infty}\sqrt{2m+1}\;s(2m+1) = \sqrt{\pi/2}$.
\end{theorem}

\begin{proof}
By Theorem~\ref{thm:sq}, $\sqrt{2m+1}\,s(2m+1) = \sqrt{W_m}$, both sides being
non-negative. Continuity of the square root and $W_m \to \pi/2$ conclude.
\end{proof}

\begin{theorem}[even-population limit]\label{thm:evenlim}
$\displaystyle \lim_{m\to\infty}\sqrt{2m}\;s(2m) = \sqrt{2/\pi}$.
\end{theorem}

\begin{proof}
By the second identity of Theorem~\ref{thm:sq}, $(2m+1)s(2m)^2 = 1/W_m \to 2/\pi$. In
particular the sequence is bounded, so
$s(2m)^2 = \bigl[(2m+1)s(2m)^2\bigr](2m+1)^{-1} \to 0$, whence
\[
  2m\,s(2m)^2 = (2m+1)s(2m)^2 - s(2m)^2 \longrightarrow \frac{2}{\pi}.
\]
Taking square roots gives the claim.
\end{proof}

\begin{corollary}[the two constants]\label{cor:constants}
\[
  \frac{\sqrt{\pi/2}}{\sqrt{2/\pi}} = \frac{\pi}{2},
  \qquad
  \sqrt{\tfrac{2}{\pi}}\cdot\sqrt{\tfrac{\pi}{2}} = 1,
  \qquad
  \frac{2}{\pi}\cdot\frac{\pi}{2} = 1 .
\]
\end{corollary}

\begin{proof}
$\sqrt{\pi/2}/\sqrt{2/\pi} = \sqrt{(\pi/2)/(2/\pi)} = \sqrt{(\pi/2)^2} = \pi/2$ since
$\pi/2>0$; the others are immediate.
\end{proof}

Numerically $\sqrt{2/\pi} = 0.797884\ldots$, $\sqrt{\pi/2} = 1.253314\ldots$ and
$\pi/2 = 1.570796\ldots$.

\begin{remark}
The appearance of $\pi$ has a transparent source: $s(2m) = 4^{-m}\binom{2m}{m}$, whose
Stirling asymptotics is $(\pi m)^{-1/2}$. The Wallis route above is preferable because it
is exact at every $m$, and because it exhibits the ratio $\pi/2$ as a single algebraic
object $W_m$ rather than as a quotient of two independent asymptotic estimates.
\end{remark}

\section{The union bound and its sharp defect}

\begin{theorem}[union bound]\label{thm:union}
For all $v,k \ge 0$, $\; F(v,k) \le k\,s(v+k)$; that is, $p_k(n) \le k\,s(n)$.
\end{theorem}

\begin{proof}
The probabilistic content is the union bound: the wolves win only if some wolf is never
lynched, and each individual wolf is never lynched with probability $s(n)$, the population
ladder being deterministic. Formally, induct along the ladder.

\emph{Base cases.} For $k=0$ both sides are $0$. For $v=0$ the claim is $1 \le k\,s(k)$,
i.e.\ the elementary bound $n\,s(n) \ge 1$, proved by two-step induction from
$s(n+2)=s(n)\frac{n+1}{n+2}$. The case $v=1$ is a direct computation.

\emph{Inductive step.} Let $v,k \ge 0$ and put $N = v+k+3$, the population of the state
$(v+2,k+1)$. The recursion gives
\[
  N\,F(v+2,k+1) = (k+1)F(v+1,k) + (v+2)F(v,k+1).
\]
By the inductive hypotheses $F(v+1,k) \le k\,s(N-2)$ and $F(v,k+1) \le (k+1)s(N-2)$, so
\[
  N\,F(v+2,k+1) \le s(N-2)\bigl[(k+1)k + (v+2)(k+1)\bigr] = (k+1)\,s(N-2)\,(N-1),
\]
using $k+v+2 = N-1$. Since $s(N) = s(N-2)\frac{N-1}{N}$, the target bound multiplied by
$N$ is exactly $(k+1)s(N-2)(N-1)$. The two agree.
\end{proof}

The inductive step is an \emph{equality} between the two upper bounds, which is why the
union bound is asymptotically sharp.

\begin{definition}[defect]\label{def:defect}
$D_k(n) = k\,s(n) - p_k(n) \ge 0$.
\end{definition}

\begin{theorem}[defect recursion]\label{thm:defectrec}
For every population $n$ and every $k \ge 0$ (with $v = n-k-3 \ge 0$),
\[
  n\,D_{k+1}(n) \;=\; (k+1)\,D_k(n-2) \;+\; (n-k-1)\,D_{k+1}(n-2).
\]
\end{theorem}

\begin{proof}
The state in question is $(v+2,k+1)$ with population $n$; the states $(v+1,k)$ and
$(v,k+1)$ both have population $n-2$, and $n-k-1 = v+2$. Expanding
Definition~\ref{def:defect} and using the recursion
$n\,F(v+2,k+1) = (k+1)F(v+1,k) + (v+2)F(v,k+1)$, both sides equal
\[
  (\text{survival part}) \;-\; \bigl[(k+1)F(v+1,k) + (v+2)F(v,k+1)\bigr],
\]
with the survival parts $n(k+1)s(n)$ and $s(n-2)\bigl[(k+1)k+(v+2)(k+1)\bigr]$
respectively. These agree, since
$s(n-2)(k+1)(k+v+2) = (k+1)s(n-2)(n-1) = n(k+1)s(n)$ by $s(n) = s(n-2)\frac{n-1}{n}$.
\end{proof}

The cancellation of the survival term in Theorem~\ref{thm:defectrec} is the structural
reason the defect is easier to control than the probability itself.

\begin{theorem}[sharp defect bound]\label{thm:sharp}
For all $v,k \ge 0$ with $n = v+k$,
\[
  n\,D_k(n) \;\le\; \binom{k}{2} = \frac{k(k-1)}{2}.
\]
Equivalently, $k\,s(n) - \dfrac{k(k-1)/2}{n} \le p_k(n) \le k\,s(n)$ for $n \ge 1$.
\end{theorem}

\begin{proof}[Proof sketch]
Set $g_k(n) = n\,D_k(n)$. Dividing Theorem~\ref{thm:defectrec} by $n-2$ gives
\[
  g_{k+1}(n) = \frac{(k+1)\,g_k(n-2) + (n-k-1)\,g_{k+1}(n-2)}{n-2}.
\]
The constant profile $g_k \equiv \binom{k}{2}$ is an exact fixed point: using Pascal's
rule $\binom{k+1}{2} = \binom{k}{2}+k$, the numerator becomes
\[
  (k+1)\binom{k}{2} + (n-k-1)\Bigl[\binom{k}{2}+k\Bigr]
  = n\binom{k}{2} + k(n-k-1) = (n-2)\binom{k+1}{2}.
\]
Hence induction on $k$ with an inner induction along the population ladder propagates the
bound, provided the two base populations ($v=0$ and $v=1$) satisfy it. Those follow from
the elementary estimates $k\,s(k) \le (k+1)/2$ and $n\,s(n)^2 \le 2$, the latter a purely
rational consequence of Theorem~\ref{thm:coupling} and $s(2m) \le s(2m+1)$.
\end{proof}

\begin{theorem}[optimality of the constant]\label{thm:optimal}
For $k = 2$ and $k = 3$ the bound of Theorem~\ref{thm:sharp} is attained exactly at every
odd population:
\[
  n\,D_2(n) = 1 \quad (n \text{ odd}), \qquad n\,D_3(n) = 3 \quad (n \text{ odd}).
\]
\end{theorem}

This follows from the closed forms of Section~\ref{sec:closed}; in particular the constant
$\binom{k}{2}$ cannot be improved.

\begin{remark}
The bound necessarily degrades in $k$. At $v=0$ the wolves win outright, $p_k(k) = 1$,
while $k\,s(k) \asymp \sqrt{k}$, so $n\,D_k(n)$ already grows like $k^{3/2}$ there. The
point of Theorem~\ref{thm:sharp} is that for each \emph{fixed} $k$ the defect is $O(1/n)$,
hence negligible against the $n^{-1/2}$ leading term.
\end{remark}

\section{The main theorem: two asymptotic expansions}

\begin{theorem}[transfer principle]\label{thm:transfer}
Let $k \ge 0$ be fixed and let $(n_m)$ be a sequence of populations with $n_m \to \infty$,
$n_m \ge k$ eventually, and $\sqrt{n_m}\,s(n_m) \to L$. Then
$\sqrt{n_m}\,p_k(n_m) \to kL$.
\end{theorem}

\begin{proof}
By Theorem~\ref{thm:sharp},
$k\,s(n_m) - \binom{k}{2}/n_m \le p_k(n_m) \le k\,s(n_m)$. Multiplying by
$\sqrt{n_m}>0$,
\[
  k\sqrt{n_m}\,s(n_m) - \binom{k}{2}\frac{1}{\sqrt{n_m}}
  \;\le\; \sqrt{n_m}\,p_k(n_m) \;\le\; k\sqrt{n_m}\,s(n_m).
\]
Both outer terms converge to $kL$; the squeeze theorem concludes.
\end{proof}

\begin{theorem}[parity dichotomy]\label{thm:main}
Fix $k \ge 1$. Then:
\begin{enumerate}
  \item along both parity classes $p_k(n) \to 0$, so the village win probability tends to
  $1$;
  \item
  $\displaystyle \lim_{\substack{n\to\infty\\ n \text{ even}}}\sqrt{n}\,p_k(n)
   = k\sqrt{\frac{2}{\pi}}$ and
   $\displaystyle \lim_{\substack{n\to\infty\\ n \text{ odd}}}\sqrt{n}\,p_k(n)
   = k\sqrt{\frac{\pi}{2}}$;
  \item the two constants are distinct and their ratio is
  $\dfrac{k\sqrt{\pi/2}}{k\sqrt{2/\pi}} = \dfrac{\pi}{2}$, independently of $k$;
  \item consequently the sequence $\bigl(\sqrt{n}\,p_k(n)\bigr)_n$ does not converge.
\end{enumerate}
\end{theorem}

\begin{proof}
Item (2) is Theorem~\ref{thm:transfer} applied to $n_m = 2m$ with $L = \sqrt{2/\pi}$
(Theorem~\ref{thm:evenlim}) and to $n_m = 2m+1$ with $L = \sqrt{\pi/2}$
(Theorem~\ref{thm:oddlim}). Item (3) is Corollary~\ref{cor:constants} together with
$2/\pi < \pi/2$, which holds because $\pi^2 > 4$. Item (1) follows from (2) on dividing by
$\sqrt{n}\to\infty$. For (4): a limit $L$ would force both subsequential limits to equal
$L$, contradicting (3) for $k \ge 1$.
\end{proof}

\begin{corollary}[the two expansions]\label{cor:expansions}
For every fixed $k \ge 1$, with $V_k(n) = 1 - p_k(n)$,
\[
  V_k(n) = 1 - k\sqrt{\tfrac{2}{\pi}}\,n^{-1/2} + o(n^{-1/2}) \quad (n \text{ even}),
\]
\[
  V_k(n) = 1 - k\sqrt{\tfrac{\pi}{2}}\,n^{-1/2} + o(n^{-1/2}) \quad (n \text{ odd}).
\]
The leading terms agree; the first-order coefficients differ by the factor $\pi/2$.
\end{corollary}

\begin{theorem}[explicit error bound]\label{thm:errorbound}
For all $v,k$ with $n = v+k \ge 1$,
\[
  \bigl|\sqrt{n}\,p_k(n) - k\sqrt{n}\,s(n)\bigr| \;\le\; \frac{k(k-1)/2}{\sqrt{n}} .
\]
\end{theorem}

\begin{proof}
Multiply Theorem~\ref{thm:sharp} by $\sqrt{n}$.
\end{proof}

Theorem~\ref{thm:errorbound} makes the convergence quantitative and explains the
numerically slower convergence for larger $k$: at $k=3$ and $n=1281$ the defect
contributes $3/\sqrt{1281} \approx 0.0838$, which accounts almost exactly for the gap
between the observed $\sqrt{n}\,p_3(n) = 3.6754$ and the limit $3\sqrt{\pi/2} = 3.7599$.

\section{The dichotomy at finite population}

\begin{lemma}[termwise comparison]\label{lem:compare}
For every $m \ge 0$, $\; s(2m) \le s(2m+1)$.
\end{lemma}

\begin{proof}
The $j$-th factors of the two products are $\frac{2j-1}{2j}$ and $\frac{2j}{2j+1}$, and
$(2j-1)(2j+1) = 4j^2-1 < 4j^2$; the products have the same number of factors.
\end{proof}

\begin{theorem}[finite-population separator]\label{thm:separator}
For every $n \ge 1$,
\[
  n\,s(n)^2 < 1 \quad (n \text{ even}), \qquad n\,s(n)^2 \ge 1 \quad (n \text{ odd}).
\]
In particular $n\,p_1(n)^2 < 1$ for even $n$ and $\ge 1$ for odd $n$.
\end{theorem}

\begin{proof}
By Lemma~\ref{lem:compare} and Theorem~\ref{thm:coupling},
\[
  s(2m)^2 \le s(2m)s(2m+1) = \frac{1}{2m+1} \le s(2m+1)^2 .
\]
Multiplying by $2m+1>0$ gives $(2m+1)s(2m)^2 \le 1 \le (2m+1)s(2m+1)^2$; the odd case is
the right-hand inequality, and for the even case $2m\,s(2m)^2 < (2m+1)s(2m)^2 \le 1$ since
$s(2m)>0$. Finally $p_1(n) = s(n)$ by Theorem~\ref{thm:onewolf}.
\end{proof}

\begin{corollary}
The threshold $1$ in Theorem~\ref{thm:separator} is exactly the geometric mean of the two
asymptotic values $2/\pi$ and $\pi/2$ of $n\,s(n)^2$.
\end{corollary}

